To quickly estimate, let's count houses on the line above the road (top side). If the distribution is sparse, two towers may suffice for those.

```python
# filename: top_side_houses.py

def top_side_houses(file_path):
    with open(file_path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]
    # Using the road index from a preliminary scan
    road_idx = None
    max_dash = -1
    for i, line in enumerate(lines):
        d = line.count('-')
        if d > max_dash:
            max_dash = d
            road_idx = i
    top_idx = road_idx - 1 if road_idx is not None and road_idx - 1 >= 0 else None
    positions = []
    if top_idx is not None:
        for pos, ch in enumerate(lines[top_idx]):
            if ch == 'H':
                positions.append(pos)
    return {'top_idx': top_idx, 'count': len(positions), 'positions': positions}

