# filename: scan_both_sides.py

def scan_both(file_path):
    with open(file_path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]
    road_idx = max(range(len(lines)), key=lambda i: lines[i].count('-'))
    positions = []
    for neighbor in [road_idx - 1, road_idx + 1]:
        if 0 <= neighbor < len(lines):
            for pos, ch in enumerate(lines[neighbor]):
                if ch == 'H':
                    positions.append(pos)
    return sorted(set(positions))

